import { NgTemplateOutlet } from '@angular/common';
import { Component, TemplateRef, contentChild, input, signal } from '@angular/core';
import { CategoryDemo, CategoryDemoItem } from './ap-category-selection.interface';

export interface CategoryVariantContext<T extends CategoryDemoItem> {
  $implicit: T;
  category: CategoryDemo<T>;
}

@Component({
  selector: 'ap-category-selection',
  imports: [NgTemplateOutlet],
  templateUrl: './ap-category-selection.component.html',
  styleUrl: './ap-category-selection.component.css',
})
export class ApCategorySelectionComponent<
  T extends CategoryDemoItem = CategoryDemoItem,
> {
  categories = input.required<CategoryDemo<T>[]>();
  getCodeSnippet = input.required<(variant: T) => string>();

  variantTemplate = contentChild<TemplateRef<CategoryVariantContext<T>>>(
    'variantTemplate',
  );

  copiedSnippet = signal<string | null>(null);

  async copyCodeSnippet(variant: T): Promise<void> {
    const snippet = this.getCodeSnippet()(variant);
    const copied = await this.copyToClipboard(snippet);

    this.copiedSnippet.set(copied ? variant.subtitle : null);
  }

  private async copyToClipboard(text: string): Promise<boolean> {
    if (navigator.clipboard && window.isSecureContext) {
      try {
        await navigator.clipboard.writeText(text);
        return true;
      } catch {
        return this.copyToClipboardFallback(text);
      }
    }

    return this.copyToClipboardFallback(text);
  }

  private copyToClipboardFallback(text: string): boolean {
    const textarea = document.createElement('textarea');
    textarea.value = text;
    textarea.style.position = 'fixed';
    textarea.style.opacity = '0';

    document.body.appendChild(textarea);
    textarea.select();

    try {
      return document.execCommand('copy');
    } finally {
      document.body.removeChild(textarea);
    }
  }
}
