import { Component, computed, signal } from '@angular/core';
import { ApCategorySelectionComponent } from '../ap-category-selection/ap-category-selection.component';
import { ApCheckBoxComponent } from '../ap-check-box/ap-check-box';
import { ApSelectComponent } from '../ap-select/ap-select.component';
import { CheckBoxCategory, CheckBoxVariantDemo } from './ap-check-box-list.interface';

@Component({
  selector: 'ap-check-box-list',
  imports: [ApCategorySelectionComponent, ApCheckBoxComponent, ApSelectComponent,],
  templateUrl: './ap-check-box-list.component.html',
  styleUrl: './ap-check-box-list.component.css',
})
export class ApCheckBoxListComponent {
  checkBoxCategories = signal<CheckBoxCategory[]>([
    {
      title: 'Sizes',
      variants: [
        { subtitle: 'Small', label: 'Small checkbox', size: 'small', checked: false },
        { subtitle: 'Medium', label: 'Medium checkbox', size: 'medium', checked: false },
        { subtitle: 'Large', label: 'Large checkbox', size: 'large', checked: false },
      ],
    },
    {
      title: 'States',
      variants: [
        { subtitle: 'Unchecked', label: 'Unchecked' },
        { subtitle: 'Checked', label: 'Checked', checked: true },
        { subtitle: 'Disabled', label: 'Disabled', disabled: true },
        { subtitle: 'Disabled Checked', label: 'Disabled checked', checked: true, disabled: true },
      ],
    },
    {
      title: 'Accent Colors',
      variants: [
        { subtitle: 'Orange', label: 'Orange', checked: true, accentColor: 'orange' },
        { subtitle: 'Yellow', label: 'Yellow', checked: true, accentColor: 'yellow' },
        { subtitle: 'Purple', label: 'Purple', checked: true, accentColor: 'purple' },
        { subtitle: 'Violet', label: 'Violet', checked: true, accentColor: 'violet' },
        { subtitle: 'Green', label: 'Green', checked: true, accentColor: 'green' },
        { subtitle: 'Sky', label: 'Sky', checked: true, accentColor: 'sky' },
        { subtitle: 'Red', label: 'Red', checked: true, accentColor: 'red' },
        { subtitle: 'Zinc', label: 'Zinc', checked: true, accentColor: 'zinc' },
        { subtitle: 'Black', label: 'Black', checked: true, accentColor: 'black' },
      ],
    },
  ]);

  selectedCategory = signal('all');

  categoryOptions = computed(() =>
    this.checkBoxCategories().map((category) => ({
      value: category.title,
      label: category.title,
    })),
  );

  filteredCategories = computed(() => {
    const selectedCategory = this.selectedCategory();
    const categories = this.checkBoxCategories();

    return selectedCategory === 'all'
      ? categories
      : categories.filter((category) => category.title === selectedCategory);
  });

  onCategoryChange(value: string | null): void {
    this.selectedCategory.set(value || 'all');
  }

  getCodeSnippet(variant: CheckBoxVariantDemo): string {
    const attrs: string[] = [];

    if (variant.label) attrs.push(`[label]="'${variant.label}'"`);
    if (variant.checked) attrs.push(`[(checked)]="checked"`);
    if (variant.disabled) attrs.push(`[disabled]="true"`);
    if (variant.accentColor && variant.accentColor !== 'orange') {
      attrs.push(`[accentColor]="'${variant.accentColor}'"`);
    }
    if (variant.size && variant.size !== 'medium') {
      attrs.push(`[size]="'${variant.size}'"`);
    }

    return `<ap-check-box ${attrs.join(' ')}></ap-check-box>`;
  }
}
