import { Component, signal, computed } from "@angular/core";
import { ApRadio } from "../ap-radio/ap-radio";
import { ApSelectComponent } from "../ap-select/ap-select.component";
import { RadioCategory, RadioVariant } from "./ap-radio-list.interface";
import { ApCategorySelectionComponent } from "../ap-category-selection/ap-category-selection.component";

@Component({
  selector: "ap-radio-list",
  imports: [ApRadio, ApSelectComponent,ApCategorySelectionComponent],
  templateUrl: "./ap-radio-list.component.html",
  styleUrl: "./ap-radio-list.component.css",
})
export class ApRadioListComponent {
  radioCategories = signal<RadioCategory[]>([
    {
      title: "States",
      variants: [
        {
          subtitle: "None Selected",
          groupName: "states-none",
          options: [
            { value: "option1", label: "selected", checked: true },
            { value: "option2", label: "unselected", checked: false },
            {
              value: "option3",
              label: "disabled",
              checked: false,
              disabled: true,
            },
          ],
        },
      ],
    },
  ]);

  selectedCategory = signal("all");

  categoryOptions = computed(() =>
    this.radioCategories().map((c) => ({ value: c.title, label: c.title }))
  );

  filteredCategories = computed(() => {
    const category = this.selectedCategory();
    return category === "all"
      ? this.radioCategories()
      : this.radioCategories().filter((c) => c.title === category);
  });

  onCategoryChange(value: string | null): void {
    this.selectedCategory.set(value || "all");
  }

  getCodeSnippet(variant: RadioVariant): string {
    const snippets = variant.options.map((option) => {
      const attrs: string[] = [];
      attrs.push(`name="${variant.groupName}"`);
      attrs.push(`value="${option.value}"`);
      if (option.checked) attrs.push(`[checked]="true"`);
      if (option.disabled) attrs.push(`[disabled]="true"`);

      return `<ap-radio ${attrs.join(" ")}>${option.label}</ap-radio>`;
    });

    return snippets.join("\n");
  }
}
