import { Component, HostBinding, input } from '@angular/core';
import { CommonModule } from '@angular/common';
import { BadgeSize, BadgeAccentColor } from './ap-badge.interface';

@Component({
  selector: 'ap-badge',
  imports: [CommonModule],
  host: {display: 'inline-block'},
  templateUrl: './ap-badge.component.html',
})
export class ApBadgeComponent {
  readonly size = input<BadgeSize>('md');
  readonly accentColor = input<BadgeAccentColor>('orange');
  readonly value = input<string | number>('');

  @HostBinding('class')
  get hostSizeClass(): string {
    const sizes = {
      xs: 'text-xs size-4 aspect-square',
      sm: 'text-sm size-6 aspect-square',
      md: 'text-base size-8 aspect-square',
      lg: 'text-lg size-10 aspect-square',
    };
    return sizes[this.size()];
  }

  getAccentColorClasses() {
    const variants = {
      orange: 'bg-orange-500 text-white',
      green: 'bg-green-500 text-zinc-950',
      blue: 'bg-blue-500 text-white',
      yellow: 'bg-yellow-500 text-zinc-950',
      red: 'bg-red-500 text-white',
    };
    return variants[this.accentColor()];
  }

}
