import { Component, signal, computed } from '@angular/core';
import { ApSelectComponent } from '../ap-select/ap-select.component';
import { SelectCategory, SelectVariant } from './ap-select-list.interface';
import { ApCategorySelectionComponent } from '../ap-category-selection/ap-category-selection.component';

@Component({
  selector: 'ap-select-list',
  imports: [ApSelectComponent, ApCategorySelectionComponent],
  templateUrl: './ap-select-list.component.html',
  styleUrl: './ap-select-list.component.css'
})
export class ApSelectListComponent {
  sampleOptions = [
    { value: 'option1', label: 'Option 1' },
    { value: 'option2', label: 'Option 2' },
    { value: 'option3', label: 'Option 3' },
    { value: 'option4', label: 'Option 4' }
  ];

  selectCategories = signal<SelectCategory[]>([
    {
      title: 'Size',
      variants: [
        { subtitle: 'Small', size: 'small', placeholder: 'Select an option', selected: null },
        { subtitle: 'Default', size: 'medium', placeholder: 'Select an option', selected: 'option2' },
        { subtitle: 'Large', size: 'large', placeholder: 'Select an option', selected: 'option2' }

      ]
    },
    {
      title: 'Variant',
      variants: [
        { subtitle: 'default', variant: 'default', placeholder: 'Select an option', selected: null },
        { subtitle: 'game-ui', variant: 'game-ui', placeholder: 'Select an option', selected: 'option2' }
      ]
    },
    {
      title: 'Accent Colors',
      variants: [
        { subtitle: 'Orange', accentColor: 'orange', selected: 'option2' },
        { subtitle: 'Yellow', accentColor: 'yellow', selected: 'option2' }
      ]
    },
  ]);

  selectedCategory = signal('all');

  categoryOptions = computed(() =>
    this.selectCategories().map(c => ({ value: c.title, label: c.title }))
  );

  filteredCategories = computed(() => {
    const category = this.selectedCategory();
    return category === 'all'
      ? this.selectCategories()
      : this.selectCategories().filter(c => c.title === category);
  });

  onCategoryChange(value: string | null): void {
    this.selectedCategory.set(value || 'all');
  }

  getCodeSnippet(variant: SelectVariant): string {
    const attrs: string[] = [];

    if (variant.size && variant.size !== 'medium') attrs.push(`[size]="'${variant.size}'"`);
    if (variant.variant && variant.variant !== 'default') attrs.push(`[variant]="'${variant.variant}'"`);
    if (variant.accentColor && variant.accentColor !== 'orange') attrs.push(`[accentColor]="'${variant.accentColor}'"`);
    if (variant.placeholder) attrs.push(`placeholder="${variant.placeholder}"`);
    if (variant.selected) attrs.push(`[selected]="'${variant.selected}'"`);
    attrs.push(`[options]="options"`);

    return `<ap-select ${attrs.join(' ')}></ap-select>`;
  }
}
