import { Component, input, model, output } from "@angular/core";
import { CommonModule } from "@angular/common";
import { CheckBoxAccentColor } from '../ap-check-box/ap-check-box.interface';
import { ApIconComponent } from "../ap-icon/ap-icon.component";

@Component({
  selector: "ap-check-box",
  imports: [CommonModule, ApIconComponent],
  templateUrl: "./ap-check-box.html",
  styleUrl: "./ap-check-box.css",
})
export class ApCheckBoxComponent {
  label = input<string>("");
  checked = model<boolean>(false);
  disabled = input<boolean>(false);
  accentColor = input<CheckBoxAccentColor>("orange");
  size = input<"small" | "medium" | "large">("medium");

  changed = output<boolean>();

  get boxSizeClasses(): string {
    switch (this.size()) {
      case "small": return "size-4 rounded-xs aspect-square";
      case "medium": return "size-5 rounded-sm  aspect-square";
      case "large": return "size-6 rounded-md aspect-square";
    }
  }

  get labelSizeClasses(): string {
    switch (this.size()) {
      case "small": return "text-xs";
      case "medium": return "text-sm";
      case "large": return "text-base";
    }
  }

  get boxAccentClasses(): string {
    const classes: string[] = [];

    switch (this.accentColor()) {
      case "orange":
        classes.push(
          "peer-hover:border-orange-500",
          "peer-checked:bg-orange-500",
          "peer-checked:border-orange-500"
        );
        break;
      case "yellow":
        classes.push(
          "peer-hover:border-yellow-400",
          "peer-checked:bg-yellow-400",
          "peer-checked:border-yellow-400"
        );
        break;
      case "purple":
        classes.push(
          "peer-hover:border-purple-500",
          "peer-checked:bg-purple-500",
          "peer-checked:border-purple-500"
        );
        break;
      case "violet":
        classes.push(
          "peer-hover:border-violet-600",
          "peer-checked:bg-violet-600",
          "peer-checked:border-violet-600"
        );
        break;
      case "green":
        classes.push(
          "peer-hover:border-green-500",
          "peer-checked:bg-green-500",
          "peer-checked:border-green-500"
        );
        break;
      case "sky":
        classes.push(
          "peer-hover:border-sky-500",
          "peer-checked:bg-sky-500",
          "peer-checked:border-sky-500"
        );
        break;
      case "red":
        classes.push(
          "peer-hover:border-red-500",
          "peer-checked:bg-red-500",
          "peer-checked:border-red-500"
        );
        break;
      case "zinc":
        classes.push(
          "peer-hover:border-zinc-500",
          "peer-checked:bg-zinc-500",
          "peer-checked:border-zinc-500"
        );
        break;
      case "black":
        classes.push(
          "peer-hover:border-zinc-500",
          "peer-checked:bg-zinc-900",
          "peer-checked:border-zinc-500"
        );
        break;
    }

    return classes.join(" ");
  }

  get wrapperHoverClass(): string {
    const classes: string[] = [];

    if (this.disabled()) {
      classes.push("opacity-50", "cursor-not-allowed");
      return classes.join(" ");
    }

    switch (this.accentColor()) {
      case "orange":
        classes.push("hover:bg-orange-500/10 p-1.5 rounded-md");
        break;
      case "yellow":
        classes.push("hover:bg-yellow-400/10 p-1.5 rounded-md");
        break;
      case "purple":
        classes.push("hover:bg-purple-500/10 p-1.5 rounded-md");
        break;
      case "violet":
        classes.push("hover:bg-violet-600/10 p-1.5 rounded-md");
        break;
      case "green":
        classes.push("hover:bg-green-500/10 p-1.5 rounded-md");
        break;
      case "sky":
        classes.push("hover:bg-sky-500/10 p-1.5 rounded-md");
        break;
      case "red":
        classes.push("hover:bg-red-500/10 p-1.5 rounded-md");
        break;
      case "zinc":
        classes.push("hover:bg-zinc-500/10 p-1.5 rounded-md");
        break;
      case "black":
        classes.push("hover:bg-zinc-900/10 p-1.5 rounded-md");
        break;
    }

    return classes.join(" ");
  }

  handleChange(event: Event): void {
    const value = (event.target as HTMLInputElement).checked;
    this.checked.set(value);
    this.changed.emit(value);
  }
}
