import { Component, OnDestroy, signal } from '@angular/core';
import { ApIconComponent } from "../ap-icon/ap-icon.component";
import { UTILITY_ICONS } from '../ap-icon/utility-icons';

@Component({
  selector: 'ap-icon-list',
  imports: [ApIconComponent],
  templateUrl: './ap-icon-list.component.html',
  styleUrl: './ap-icon-list.component.css'
})
export class ApIconListComponent implements OnDestroy {
  private copiedIconNameResetTimer: ReturnType<typeof setTimeout> | null = null;
  readonly copiedIconName = signal<string | null>(null);
  readonly iconNames: string[] = Object.entries(UTILITY_ICONS).flatMap(([key, variants]) =>
    Object.keys(variants).map(style =>
      style === 'default' ? key : `${key} ${style}`
    )
  );

  async copyIconName(name: string): Promise<void> {
    const copied = await this.copyToClipboard(name);

    if (!copied) {
      return;
    }

    this.copiedIconName.set(name);

    if (this.copiedIconNameResetTimer) {
      clearTimeout(this.copiedIconNameResetTimer);
    }

    this.copiedIconNameResetTimer = setTimeout(() => {
      this.copiedIconName.set(null);
      this.copiedIconNameResetTimer = null;
    }, 1500);
  }

  ngOnDestroy(): void {
    if (this.copiedIconNameResetTimer) {
      clearTimeout(this.copiedIconNameResetTimer);
    }
  }

  private async copyToClipboard(text: string): Promise<boolean> {
    if (navigator.clipboard && window.isSecureContext) {
      try {
        await navigator.clipboard.writeText(text);
        return true;
      } catch {
        return this.copyToClipboardFallback(text);
      }
    }

    return this.copyToClipboardFallback(text);
  }

  private copyToClipboardFallback(text: string): boolean {
    const textarea = document.createElement('textarea');
    textarea.value = text;
    textarea.style.position = 'fixed';
    textarea.style.opacity = '0';

    document.body.appendChild(textarea);
    textarea.select();

    try {
      return document.execCommand('copy');
    } finally {
      document.body.removeChild(textarea);
    }
  }
}
