import { Component, computed, signal } from '@angular/core';
import { ApButtonComponent } from '../ap-button/ap-button.component';
import { ApSelectComponent } from '../ap-select/ap-select.component';
import { ApCategorySelectionComponent } from '../ap-category-selection/ap-category-selection.component';
import { ButtonAccentColor, ButtonVariant } from '../ap-button/ap-button.interface';
import { ButtonCategory, ButtonVariantDemo } from './ap-button-list.interface';

const ACCENT_COLORS: { value: ButtonAccentColor; label: string }[] = [
  { value: 'orange', label: 'Orange' },
  { value: 'yellow', label: 'Yellow' },
  { value: 'purple', label: 'Purple' },
  { value: 'violet', label: 'Violet' },
  { value: 'pink', label: 'Pink' },
  { value: 'slate', label: 'Slate' },
  { value: 'green', label: 'Green' },
  { value: 'sky', label: 'Sky' },
  { value: 'orange-dark', label: 'Orange Dark' },
  { value: 'red', label: 'Red' },
  { value: 'zinc', label: 'Zinc' },
  { value: 'white', label: 'White' },
];

const VARIANTS: { value: ButtonVariant; label: string }[] = [
  { value: 'content', label: 'Default' },
  { value: 'content-rounded', label: 'Rounded' },
  { value: 'outlined', label: 'Outlined' },
  { value: 'outlined-rounded', label: 'Rounded Outlined' },
  { value: 'raised', label: 'Raised' },
  { value: 'text', label: 'Text' },
];

@Component({
  selector: 'ap-button-list',
  imports: [ApButtonComponent, ApSelectComponent, ApCategorySelectionComponent],
  templateUrl: './ap-button-list.component.html',
  styleUrl: './ap-button-list.component.css',
})
export class ApButtonListComponent {
  buttonCategories = signal<ButtonCategory[]>([
    {
      title: 'Sizes',
      variants: [
        { subtitle: 'X-Small', label: 'X-small Button', size: 'x-small' },
        { subtitle: 'Small', label: 'Small Button', size: 'small' },
        { subtitle: 'Medium', label: 'Medium Button', size: 'medium' },
        { subtitle: 'Large', label: 'Large Button', size: 'large' },
      ],
    },
    {
      title: 'Variants',
      variants: VARIANTS.flatMap((variant) =>
        ACCENT_COLORS.map((color) => ({
          subtitle: `${variant.label} · ${color.label}`,
          label: variant.label,
          variant: variant.value,
          accentColor: color.value,
        })),
      ),
    },
    {
      title: 'With Icons',
      variants: [
        {
          subtitle: 'Icon Left',
          label: 'Search',
          icon: 'search',
          iconPos: 'left',
        },
        {
          subtitle: 'Icon Right',
          label: 'Next',
          icon: 'chevron-right',
          iconPos: 'right',
        },
        {
          subtitle: 'Icon Only',
          label: '',
          icon: 'star',
          variant: 'content-rounded',
        },
      ],
    },
    {
      title: 'States',
      variants: [
        { subtitle: 'Normal', label: 'Normal' },
        { subtitle: 'Disabled', label: 'Disabled', disabled: true },
        { subtitle: 'Loading', label: 'Loading', loading: true },
      ],
    },
  ]);

  selectedCategory = signal('all');

  categoryOptions = computed(() =>
    this.buttonCategories().map((c) => ({
      value: c.title,
      label: c.title,
    })),
  );

  filteredCategories = computed(() => {
    const category = this.selectedCategory();
    const categories = this.buttonCategories();

    return category === 'all'
      ? categories
      : categories.filter((item) => item.title === category);
  });

  onCategoryChange(value: string | null): void {
    this.selectedCategory.set(value || 'all');
  }

  getCodeSnippet(variant: ButtonVariantDemo): string {
    const attrs: string[] = [];

    if (variant.label) attrs.push(`[label]="'${variant.label}'"`);
    if (variant.accentColor)
      attrs.push(`[accentColor]="'${variant.accentColor}'"`);
    if (variant.variant && variant.variant !== 'content')
      attrs.push(`[variant]="'${variant.variant}'"`);
    if (variant.icon) attrs.push(`[icon]="'${variant.icon}'"`);
    if (variant.iconPos && variant.iconPos !== 'left')
      attrs.push(`[iconPos]="'${variant.iconPos}'"`);
    if (variant.size && variant.size !== 'medium')
      attrs.push(`[size]="'${variant.size}'"`);
    if (variant.disabled) attrs.push(`[disabled]="true"`);
    if (variant.loading) attrs.push(`[loading]="true"`);

    return `<ap-button ${attrs.join(' ')}></ap-button>`;
  }
}
