import { Component, signal, computed } from '@angular/core';
import { ApInputBox } from '../ap-input-box/ap-input-box';
import { ApSelectComponent } from '../ap-select/ap-select.component';
import { InputCategory, InputVariant } from './ap-input-list.interface';
import { ApCategorySelectionComponent } from '../ap-category-selection/ap-category-selection.component';


@Component({
  selector: 'ap-input-list',
  imports: [ApInputBox, ApSelectComponent, ApCategorySelectionComponent],
  templateUrl: './ap-input-list.component.html',
  styleUrl: './ap-input-list.component.css'
})
export class ApInputListComponent {
  inputCategories = signal<InputCategory[]>([
    {
      title: 'Input Types',
      variants: [
        { subtitle: 'Text', label: 'Text', type: 'text', placeholder: 'Enter text' },
        { subtitle: 'Number', label: 'Number', type: 'number', placeholder: 'Enter number' },
        { subtitle: 'Email', label: 'Email', type: 'email', placeholder: 'Enter email' },
        { subtitle: 'Password', label: 'Password', type: 'password', placeholder: 'Enter password' },
        { subtitle: 'Tel', label: 'Tel', type: 'tel', placeholder: 'Enter phone' },
        { subtitle: 'URL', label: 'URL', type: 'url', placeholder: 'Enter URL' },
        { subtitle: 'Date', label: 'Date', type: 'date' },
        { subtitle: 'Time', label: 'Time', type: 'time' }
      ]
    },
    {
      title: 'Sizes',
      variants: [
        { subtitle: 'Small', label: 'Small', size: 'small', placeholder: 'Small input' },
        { subtitle: 'Medium', label: 'Medium', size: 'medium', placeholder: 'Medium input' },
        { subtitle: 'Large', label: 'Large', size: 'large', placeholder: 'Large input' }
      ]
    },
    {
      title: 'Accent Colors',
      variants: [
        { subtitle: 'Orange', label: 'Orange', accentColor: 'orange', placeholder: 'Orange accent' },
        { subtitle: 'Yellow', label: 'Yellow', accentColor: 'yellow', placeholder: 'Yellow accent' },
        { subtitle: 'Slate', label: 'Slate', accentColor: 'slate', placeholder: 'Slate accent' },
      ]
    },
    {
      title: 'States',
      variants: [
        { subtitle: 'Normal', label: 'Normal', placeholder: 'Normal state' },
        { subtitle: 'With Value', label: 'With Value', placeholder: 'Placeholder text', value: 'Filled value' },
        { subtitle: 'Disabled', label: 'Disabled', placeholder: 'Disabled input', disabled: true },
        { subtitle: 'Error', label: 'Error', placeholder: 'Error state', error: true },
        { subtitle: 'Success', label: 'Success', placeholder: 'Success state', value: 'Valid', success: true },
        { subtitle: 'Max Length', label: 'Max Length', placeholder: 'Max 20 characters', maxLength: 20 }
      ]
    },
    {
      title: 'With Icons',
      variants: [
        { subtitle: 'Search Icon', label: 'Search', icon: 'search', placeholder: 'Search...' },
        { subtitle: 'Email Icon', label: 'Email', icon: 'envelope', placeholder: 'Email address', type: 'email' },
      ]
    },
    {
      title: 'Prefix & Suffix',
      variants: [
        { subtitle: 'Dollar Prefix', label: 'Amount', prefix: '$', placeholder: '0.00', type: 'number' },
        { subtitle: 'Percent Suffix', label: 'Percent', suffix: '%', placeholder: '0', type: 'number' },
        { subtitle: 'URL Prefix', label: 'Website', prefix: 'https://', placeholder: 'example.com' }
      ]
    },
    {
      title: 'Currency Image',
      variants: [
        { subtitle: 'Currency Image', label: 'Currency', currencyImage: true }
      ]
    },
  ]);

  selectedCategory = signal('all');

  categoryOptions = computed(() =>
    this.inputCategories().map(c => ({ value: c.title, label: c.title }))
  );

  filteredCategories = computed(() => {
    const category = this.selectedCategory();
    return category === 'all'
      ? this.inputCategories()
      : this.inputCategories().filter(c => c.title === category);
  });

  onCategoryChange(value: string | null): void {
    this.selectedCategory.set(value || 'all');
  }

  getCodeSnippet(variant: InputVariant): string {
    const attrs: string[] = [];

    if (variant.type && variant.type !== 'text') attrs.push(`type="${variant.type}"`);
    if (variant.label) attrs.push(`label="${variant.label}"`);
    if (variant.size && variant.size !== 'medium') attrs.push(`size="${variant.size}"`);
    if (variant.accentColor && variant.accentColor !== 'orange') attrs.push(`accentColor="${variant.accentColor}"`);
    if (variant.icon) attrs.push(`icon="${variant.icon}"`);
    if (variant.placeholder) attrs.push(`placeholder="${variant.placeholder}"`);
    if (variant.value) attrs.push(`value="${variant.value}"`);
    if (variant.maxLength) attrs.push(`[maxLength]="${variant.maxLength}"`);
    if (variant.error) attrs.push(`[error]="true"`);
    if (variant.success) attrs.push(`[success]="true"`);
    if (variant.disabled) attrs.push(`[disabled]="true"`);
    if (variant.prefix) attrs.push(`prefix="${variant.prefix}"`);
    if (variant.suffix) attrs.push(`suffix="${variant.suffix}"`);
    if (variant.currencyImage === true) attrs.push(`[currencyImage]="true"`);
    if (typeof variant.currencyImage === 'string') attrs.push(`currencyImage="${variant.currencyImage}"`);

    return `<ap-input-box ${attrs.join(' ')}></ap-input-box>`;
  }
}
